import Foundation
private let offset: UInt64 = 1_469_598_103_934_665_603
private let prime: UInt64 = 1_099_511_628_211
private func hash(_ seed: UInt64, _ value: UInt64) -> UInt64 { var result = seed; for byte in 0..<8 { result ^= (value >> UInt64(byte * 8)) & 255; result &*= prime }; return result }
@main struct SM64GrandStarSmoke { static func main() { let appear = SM64GrandStarBehavior.update(.init(action: 0, timer: 0, subAction: 0, position: .zero, homeY: 0, velocityY: 0, forwardVelocity: 0, yaw: 0, angleVelocityYaw: 0, interacted: false)); let launch = SM64GrandStarBehavior.update(.init(action: 1, timer: 0, subAction: 0, position: .zero, homeY: 0, velocityY: 0, forwardVelocity: 0, yaw: 0, angleVelocityYaw: 1024, interacted: false)); let collect = SM64GrandStarBehavior.update(.init(action: 2, timer: 1, subAction: 1, position: .init(x: 1,y: 2,z: 3), homeY: 0, velocityY: 0, forwardVelocity: 0, yaw: 10, angleVelocityYaw: 0, interacted: true)); precondition(appear.playAppearsSound && appear.spawnSparkles && appear.angleVelocityYaw == 1024, "grand star appearance"); precondition(launch.action == 1 && launch.playGrandSound, "grand star launch"); precondition(collect.tangible && collect.shouldDelete, "grand star collect"); var f=offset; for o in [appear,launch,collect] { f=hash(f,UInt64(o.action)); f=hash(f,UInt64(o.timer)); f=hash(f,UInt64(o.subAction)); f=hash(f,UInt64(o.tangible ? 1:0)); f=hash(f,UInt64(o.shouldDelete ? 1:0)); f=hash(f,UInt64(o.spawnSparkles ? 1:0)); f=hash(f,UInt64(o.playAppearsSound ? 1:0)); f=hash(f,UInt64(o.playGrandSound ? 1:0)); f=hash(f,UInt64(o.playJumpSound ? 1:0)); f=hash(f,UInt64(bitPattern:Int64(o.yaw))) }; print(String(format:"grandStarFingerprint=0x%016llx",f)); print("SM64 Modern grand-star smoke passed") } }
